const ACTIVITIES=[{name:'Dance Party',mins:5,mess:'none',what:'Put on a favorite song and dance together.'},{name:'Book Basket',mins:10,mess:'none',what:'Let Bailey choose three board books and snuggle up.'},{name:'Laundry Helper',mins:10,mess:'low',what:'Invite Bailey to match socks or put washcloths in a basket.'},{name:'Painter’s Tape Roads',mins:15,mess:'low',what:'Make a simple road on the floor with painter’s tape and drive toy cars.'},{name:'Nature Treasure Walk',mins:20,mess:'low',what:'Look for leaves, birds, and different colors outside together.'},{name:'Stack & Knock Down',mins:5,mess:'none',what:'Build a block tower and let Bailey knock it down.'},{name:'Water Painting',mins:15,mess:'low',what:'Use a clean brush and a little water to paint on construction paper; supervise closely.'},{name:'Stuffed Animal Picnic',mins:10,mess:'none',what:'Set out a blanket and invite favorite stuffed animals to a pretend picnic.'}];
function itemList(key,title,placeholder){return `<section class="card"><h3>${title}</h3><div class="row-actions"><input class="field grow" id="new-${key}" maxlength="120" placeholder="${placeholder}"><button class="button" data-item-add="${key}">Add</button></div>${state[key].map((g,i)=>`<div class="grocery-line"><label class="task"><input type="checkbox" data-item-check="${key}:${i}" ${g.done?'checked':''}><span>${esc(g.label)}</span></label><button class="icon-button" data-item-remove="${key}:${i}" aria-label="Remove item">×</button></div>`).join('')||'<p class="subtle">Your list is empty for now.</p>'}<button class="button secondary" data-copy-list="${key}">♡ Copy ${key==='household'?'household items':'groceries'} for AnyList</button><p class="subtle">Copies unchecked items only. Paste them into your matching AnyList list.</p></section>`}
function recipes(){const filter=state.recipeFilter||'all';return `<section class="card peach"><h2>Family Recipe Box 🍓</h2><p class="subtle">Curated, built-in recipes—not live suggestions. Choose one meal, add its ingredients to Groceries, and make one dinner for both of you.</p><div class="row-actions">${[['all','All'],['dinner','Dinners'],['snack','Snacks'],['breakfast','Breakfast'],['favorites','♡ Favorites']].map(([v,t])=>`<button class="button ${filter===v?'':'secondary'}" data-recipe-filter="${v}">${t}</button>`).join('')}</div></section>${RECIPES.filter(r=>filter==='all'||(filter==='favorites'?state.favorites.includes(r.id):r.type===filter)).map(r=>`<section class="card"><div class="topline"><h3>${esc(r.name)}</h3><span class="pill">${r.time} min</span></div><p class="subtle">${r.type==='snack'?'After-daycare snack':'Family-friendly '+r.type} · ${esc(r.tip)}</p><b>Ingredients</b><p>${r.ingredients.map(esc).join(' · ')}</p><details><summary>See simple directions</summary><ol>${r.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></details><div class="row-actions"><button class="button" data-recipe-add="${r.id}">+ Ingredients to Groceries</button><button class="button secondary" data-recipe-favorite="${r.id}">${state.favorites.includes(r.id)?'♥ Saved':'♡ Save'}</button></div></section>`).join('')||'<section class="card">No recipes here yet. Try another filter.</section>'}`}
function cottageKitchen(){return `<div class="welcome"><span class="eyebrow">✿ THE COTTAGE KITCHEN</span><h2>Meals, snacks & little lists</h2><p>Less wondering what to make. More time together.</p></div><section class="card sage"><h2>Tonight’s dinner shortcut</h2><p>Pick a recipe below, or keep your existing weekly meal plan.</p><button class="button" data-kitchen-view="recipes">Open recipe box ♡</button> <button class="button secondary" data-kitchen-view="lists">Shopping lists</button> <button class="button secondary" data-kitchen-view="plan">Weekly plan</button></section>${kitchenView==='recipes'?recipes():kitchenView==='lists'?itemList('groceries','🥕 Groceries','Milk, bananas, chicken…')+itemList('household','🧺 Household essentials','Diapers, wipes, detergent…'):`${plan()}`}<p class="subtle">Tip: Your original meal plan and grocery notes are still available in Weekly plan.</p>`}
let kitchenView='recipes';
function garden(){const total=state.gratitudes.length,answered=state.prayers.filter(x=>x.answered).length;const blooms=Math.min(36,total+answered);const flowers=Array.from({length:blooms},(_,i)=>{const x=12+(i*67)%276,y=28+(i*43)%95;return `<g transform="translate(${x},${y})"><path d="M0 0v28" stroke="#719676" stroke-width="2"/><path d="M0 17q-12-15-14-4q5 10 14 4M0 21q13-15 15-4q-5 9-15 4" fill="#98B98B"/>${[0,72,144,216,288].map(a=>`<ellipse cx="0" cy="-9" rx="6" ry="10" transform="rotate(${a})" fill="${['#E6B0C3','#B3C9D7','#EACB94','#C7B3DA'][i%4]}"/>`).join('')}<circle r="5" fill="#F8E9B3"/></g>`}).join('');return `<section class="card garden"><span class="eyebrow">✿ LITTLE BLESSINGS BLOOM</span><h2>Your Gratitude Garden 🌷</h2><p>Every gratitude adds a flower. Answered prayers add a bloom, too. Nothing wilts if you miss a day.</p><svg viewBox="0 0 320 170" role="img" aria-label="Garden with ${blooms} flowers" style="width:100%;max-height:240px"><path d="M0 125Q85 107 170 127T320 121V170H0Z" fill="#d9e5d1"/>${flowers}${!blooms?'<text x="160" y="78" text-anchor="middle" fill="#7a9380" font-size="13">Your first flower is waiting ♡</text>':''}</svg><p class="subtle">${total} grateful moments · ${answered} answered prayers</p></section>`}
function baileyExtras(){const weekend=[0,6].includes(new Date().getDay());const bag=['Diapers','Wipes','Spare outfit','Comfort item','Water cup'];const idx=(new Date().getDate()+new Date().getMonth()*31)%ACTIVITIES.length;const a=ACTIVITIES[idx];return `<section class="card peach"><h2>Bailey’s Little World 🧸</h2><p>Ideas for connection, not more work.</p><h3>One sweet thing today</h3><p><b>${esc(a.name)}</b> · ${a.mins} minutes · ${esc(a.what)}</p><button class="button secondary" id="new-activity">Surprise us with another activity ♡</button><p id="activity-result" class="subtle"></p></section><section class="card"><h3>Daycare bag 🎒</h3><p class="subtle">${weekend?'Weekend! No daycare bag needed today. You can still prepare for Monday.':'A simple bag check; no need to repack everything every day.'}</p>${bag.map((x,i)=>`<label class="task"><input type="checkbox" data-bag="${i}" ${state.baileyBag[isoDate(new Date())+':'+i]?'checked':''}><span>${x}</span></label>`).join('')}</section><section class="card"><h3>Little traditions & memories</h3><p class="subtle">Save the tiny moments you’ll want to remember someday in Bailey’s Little Moments below. You can also use it for clothing sizes and favorites.</p></section>`}
function helpingHand(){const opts=[['tired','😴 Exhausted'],['busy','⏰ Running late'],['overwhelmed','☁ Overwhelmed'],['good','🌷 Have energy']];const d=new Date().getDay(),daycareTomorrow=!([5,6].includes(d));const plans={tired:['An easy dinner or leftovers','Bailey’s bedtime and comfort',...(daycareTomorrow?['Set out daycare essentials']:[]),'Everything else can wait'],busy:['Grab the must-have items','Choose the fastest dinner','Skip nonurgent chores'],overwhelmed:['Food and water for everyone','Handle only urgent needs','Choose one tiny reset—or rest'],good:['Pick a family dinner','Enjoy 10 minutes of Bailey time','Choose one home task','Five-minute evening reset']};return `<section class="card helping"><span class="eyebrow">♡ MAMA’S HELPING HAND</span><h2>What kind of day is it?</h2><div class="row-actions">${opts.map(([id,label])=>`<button class="button ${state.energy===id?'':'secondary'}" data-energy="${id}">${label}</button>`).join('')}</div><h3>Your gentle game plan</h3>${plans[state.energy in plans?state.energy:'tired'].map((x,i)=>`<p>♡ ${esc(x)}</p>`).join('')}<p class="subtle">A suggested plan, not a new checklist. No guilt and no overdue tasks.</p></section>`}
function brain(){return `<section class="card"><h3>🧠 Mama Brain Dump</h3><p class="subtle">Get it out of your head. Add a note, then send it to Groceries, Household, or keep it as a reminder.</p><div class="row-actions"><input class="field grow" id="brain-input" maxlength="240" placeholder="Wipes, appointment, package return…"><button class="button" id="brain-add">Capture</button></div>${state.brain.map((x,i)=>`<div class="brain-line"><span>${esc(x.text)}</span><div class="row-actions"><button class="button secondary" data-brain-send="${i}:groceries">Groceries</button><button class="button secondary" data-brain-send="${i}:household">Household</button><button class="icon-button" data-brain-delete="${i}" aria-label="Remove note">×</button></div></div>`).join('')}</section>`}

function render(){normalizeMode();document.getElementById('today-label').textContent=new Intl.DateTimeFormat('en-US',{weekday:'long',month:'long',day:'numeric'}).format(new Date());document.getElementById('app').innerHTML=({today,week,calendar,reset:routines,plan:cottageKitchen,more,kids,faith}[tab]||today)();document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));updateLiveGrace()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.kitchenView){kitchenView=b.dataset.kitchenView;render()}else if(b.dataset.recipeFilter){state.recipeFilter=b.dataset.recipeFilter;render()}else if(b.dataset.recipeFavorite){const id=b.dataset.recipeFavorite;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();render()}else if(b.dataset.recipeAdd){const r=RECIPES.find(x=>x.id===b.dataset.recipeAdd);if(r){let added=0;r.ingredients.forEach(label=>{if(!state.groceries.some(x=>x.label.toLowerCase()===label.toLowerCase()&&!x.done)){state.groceries.push({label,done:false});added++}});save();alert(added+' ingredients added to Groceries.');}}else if(b.dataset.itemAdd){const key=b.dataset.itemAdd,el=document.getElementById('new-'+key);if(el?.value.trim()){state[key].push({label:el.value.trim().slice(0,120),done:false});save();render()}}else if(b.dataset.itemRemove){const [key,i]=b.dataset.itemRemove.split(':');state[key].splice(Number(i),1);save();render()}else if(b.dataset.copyList){const items=state[b.dataset.copyList].filter(x=>!x.done).map(x=>x.label);if(!items.length){alert('Add unchecked items first.')}else{const value=items.join('\n');if(navigator.clipboard?.writeText){navigator.clipboard.writeText(value).then(()=>alert('Copied! Paste into AnyList.')).catch(()=>prompt('Copy for AnyList:',value))}else prompt('Copy for AnyList:',value)}}else if(b.dataset.energy){state.energy=b.dataset.energy;save();render()}else if(b.id==='brain-add'){const el=document.getElementById('brain-input');if(el?.value.trim()){state.brain.unshift({text:el.value.trim().slice(0,240)});save();render()}}else if(b.dataset.brainSend){const [i,key]=b.dataset.brainSend.split(':');const x=state.brain.splice(Number(i),1)[0];if(x){state[key].push({label:x.text,done:false});save();render()}}else if(b.dataset.brainDelete){state.brain.splice(Number(b.dataset.brainDelete),1);save();render()}else if(b.id==='new-activity'){const a=ACTIVITIES[Math.floor(Math.random()*ACTIVITIES.length)];document.getElementById('activity-result').textContent=a.name+' ('+a.mins+' min): '+a.what}else if(b.dataset.tab){tab=b.dataset.tab;render();updateLiveGrace();loadDailyNLT();scrollTo(0,0)}else if(b.id==='retry-nlt'){liveNLT.status='idle';loadDailyNLT()}else if(b.dataset.mode){state.mode=b.dataset.mode;state.sickUntil=state.mode==='normal'?'':isoDate(new Date());save();render();window.scrollTo(0,0)}else if(b.dataset.extend){state.sickUntil=addDays(Number(b.dataset.extend));save();render()}else if(b.id==='save-verse'){const v=dailyVerse()[0];state.savedVerses=state.savedVerses.includes(v)?state.savedVerses.filter(x=>x!==v):[...state.savedVerses,v];save();render()}else if(b.id==='capture-add'){const el=document.getElementById('capture-input');if(el.value.trim()){state.capture.unshift({label:el.value.trim(),done:false});save();render()}}else if(b.dataset.add){const k=b.dataset.add,el=document.getElementById('new-'+k);if(el?.value.trim()){state[k].unshift({text:el.value.trim(),answered:false});save();render()}}else if(b.dataset.remove){const [k,i]=b.dataset.remove.split(':');if(confirm('Remove this entry?')){state[k].splice(Number(i),1);save();render()}}else if(b.dataset.answer!==undefined){state.prayers[Number(b.dataset.answer)].answered=!state.prayers[Number(b.dataset.answer)].answered;save();render()}else if(b.dataset.quick){const hints={10:'Try one counter, one laundry basket, or one drawer. Set a timer and stop when it rings.',company:'20-minute guest reset: bathroom sink, kitchen counters, visible clutter, then lights and a fresh towel.',dinner:'Choose an easy family dinner from your Meals tab. Leftovers count!'};document.getElementById('quick-result').textContent=hints[b.dataset.quick]}else if(b.hasAttribute('data-day')){selectedDay=Number(b.dataset.day);render()}else if(b.id==='add-task'){const label=prompt('What task would you like to add?');if(label?.trim()){state.extra.push({id:Date.now().toString(36)+Math.random().toString(36).slice(2,6),day:selectedDay,label:label.trim().slice(0,120)});save();render()}}else if(b.id==='add-grocery'){const el=document.getElementById('new-grocery');if(el.value.trim()){state.groceries.push({label:el.value.trim().slice(0,120),done:false});save();render()}}else if(b.hasAttribute('data-remove-grocery')){state.groceries.splice(Number(b.dataset.removeGrocery),1);save();render()}else if(b.id==='add-event'){const date=document.getElementById('event-date').value,label=document.getElementById('event-label').value.trim();if(date&&label){state.events.push({id:Date.now().toString(36),date,label:label.slice(0,100)});save();render()}}else if(b.hasAttribute('data-remove-event')){state.events=state.events.filter(x=>x.id!==b.dataset.removeEvent);save();render()}else if(b.id==='copy-anylist'){const items=state.groceries.filter(x=>!x.done).map(x=>x.label).filter(Boolean);const msg=document.getElementById('anylist-status');if(!items.length){msg.textContent='Add an unchecked grocery item first.';}else{const value=items.join('\n');if(navigator.clipboard?.writeText){navigator.clipboard.writeText(value).then(()=>{const n=document.getElementById('anylist-status');if(n)n.textContent='Copied! Open AnyList and paste your items.'}).catch(()=>window.prompt('Copy these items for AnyList:',value));}else{window.prompt('Copy these items for AnyList:',value);}}}else if(b.id==='add-today-nlt'){const ref=dailyVerse()[0];const value=prompt('Paste your authorized NLT verse text for '+ref+':');if(value?.trim()){state.nltTexts[ref]=value.trim().slice(0,1500);state.nltVerified={...(state.nltVerified||{}),[ref]:true};save();render();}}else if(b.id==='save-meals'){document.querySelectorAll('[data-meal]').forEach(x=>state.meals[Number(x.dataset.meal)]=x.value.slice(0,200));save();alert('Meal plan saved!')}else if(b.id==='save-notes'){state.notes=document.getElementById('notes').value;save();alert('Notes saved!')}else if(b.id==='export'){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='home-sweet-home-backup-'+isoDate(new Date())+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}else if(b.id==='import'){document.getElementById('import-file').click()}else if(b.id==='import-nlt'){document.getElementById('nlt-file').click()}else if(b.id==='clear'&&confirm('Erase all checklists, projects, meals and notes on this device?')){state=blank();save();render()}});
document.addEventListener('change',async e=>{const x=e.target;if(x.dataset.itemCheck){const [key,i]=x.dataset.itemCheck.split(':');state[key][Number(i)].done=x.checked;save();render()}else if(x.dataset.bag!==undefined){state.baileyBag[isoDate(new Date())+':'+x.dataset.bag]=x.checked;save();render()}else if(x.id==='nlt-file'&&x.files?.[0]){try{const data=JSON.parse(await x.files[0].text());if(!data||Array.isArray(data)||typeof data!=='object')throw Error('Invalid');const valid=Object.entries(data).filter(([k,v])=>DAILY_REFERENCES.includes(k)&&typeof v==='string'&&v.length<1500);if(!valid.length)throw Error('No matching references');if(!confirm('Import '+valid.length+' NLT passages from your authorized source?'))return;state.nltTexts={...(state.nltTexts||{}),...Object.fromEntries(valid)};state.nltVerified={...(state.nltVerified||{}),...Object.fromEntries(valid.map(([k])=>[k,true]))};save();render()}catch(e){alert('Could not import. Use a JSON object such as {"Psalms 1:1":"Your authorized NLT verse text"}.')}}else if(x.dataset.check){state.checks[x.dataset.check]=x.checked;save();render()}else if(x.hasAttribute('data-grocery')){state.groceries[Number(x.dataset.grocery)].done=x.checked;save();render()}else if(x.dataset.project){state.projects[x.dataset.project]=x.checked;save();render()}else if(x.dataset.maint){state.maintenance[x.dataset.maint]=x.checked;save();render()}else if(x.id==='import-file'&&x.files?.[0]){try{const obj=JSON.parse(await x.files[0].text());if(!obj||typeof obj!=='object'||Array.isArray(obj)||!obj.checks||typeof obj.checks!=='object'||Array.isArray(obj.checks)||!Array.isArray(obj.meals)||!Array.isArray(obj.groceries))throw Error('Invalid Home Sweet Home backup');if(!confirm('Replace your current app data with this backup? Export your current data first.'))return;try{localStorage.setItem(KEY+'-pre-import-'+Date.now(),JSON.stringify(state))}catch(e){};state={...blank(),...obj,groceries:Array.isArray(obj.groceries)?obj.groceries:[],events:Array.isArray(obj.events)?obj.events:[],kids:Array.isArray(obj.kids)?obj.kids:[],prayers:Array.isArray(obj.prayers)?obj.prayers:[],gratitudes:Array.isArray(obj.gratitudes)?obj.gratitudes:[],savedVerses:Array.isArray(obj.savedVerses)?obj.savedVerses:[],capture:Array.isArray(obj.capture)?obj.capture:[],mode:['normal','minimum','sick'].includes(obj.mode)?obj.mode:'normal',routineChecks:obj.routineChecks||{},sickUntil:typeof obj.sickUntil==='string'?obj.sickUntil:'',nltTexts:obj.nltTexts||{},nltVerified:obj.nltVerified||{},household:Array.isArray(obj.household)?obj.household:[],favorites:Array.isArray(obj.favorites)?obj.favorites:[],baileyBag:obj.baileyBag||{},brain:Array.isArray(obj.brain)?obj.brain:[],energy:obj.energy||'tired',recipeFilter:'all'};save();render()}catch(err){alert('Could not import that backup file.')}}});
render();updateLiveGrace();if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});

// Refresh the daily verse when the page loads and when the date changes.
window.addEventListener('load',()=>{loadDailyNLT();document.addEventListener('visibilitychange',()=>{if(!document.hidden){render();updateLiveGrace();loadDailyNLT();}});});
